INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
-- Lernfeld 1 > Planung und Anforderungsanalyse > Hardware-Systemvoraussetzungen
-- Ja/Nein-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Müssen Hardware-Systemvoraussetzungen immer die maximale Leistung eines Systems berücksichtigen?', 2, '[{"text": "Nein", "correct": true, "because": "Abhängig von Anforderungen, nicht immer maximal"}, {"text": "Ja", "correct": false, "because": "Überdimensionierung kann unnötig sein"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Hardware-Systemvoraussetzungen ohne Berücksichtigung der Software erstellt werden?', 2, '[{"text": "Nein", "correct": true, "because": "Software bestimmt Hardwarebedarf"}, {"text": "Ja", "correct": false, "because": "Softwareanforderungen sind entscheidend"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind Hardware-Systemvoraussetzungen ausschließlich für neue Systeme relevant?', 2, '[{"text": "Nein", "correct": true, "because": "Auch bestehende Systeme müssen geprüft werden"}, {"text": "Ja", "correct": false, "because": "Upgrades betreffen Bestandssysteme"}]'),
('00000000-0000-0000-0000-000000000000', 'Können Hardware-Systemvoraussetzungen während eines Projekts unverändert bleiben?', 2, '[{"text": "Nein", "correct": true, "because": "Änderungen der Anforderungen sind möglich"}, {"text": "Ja", "correct": false, "because": "Statische Voraussetzungen sind unpraktisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Müssen Hardware-Systemvoraussetzungen zwingend die Zukunftssicherheit garantieren?', 2, '[{"text": "Nein", "correct": true, "because": "Fokus liegt auf aktuellen Anforderungen"}, {"text": "Ja", "correct": false, "because": "Zukunftssicherheit ist optional"}]'),
-- Single-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor hat den größten Einfluss auf die Festlegung der Hardware-Systemvoraussetzungen?', 3, '[{"text": "Softwareanforderungen", "correct": true, "because": "Software bestimmt Hardwarebedarf"}, {"text": "Budgetvorgaben", "correct": false, "because": "Wichtig, aber sekundär"}, {"text": "Lieferzeiten", "correct": false, "because": "Logistisch, nicht technisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Hardware-Komponente wird bei den Systemvoraussetzungen primär für die Rechenleistung betrachtet?', 2, '[{"text": "Prozessor", "correct": true, "because": "Kern der Rechenleistung"}, {"text": "Netzteil", "correct": false, "because": "Versorgung, keine Leistung"}, {"text": "Festplatte", "correct": false, "because": "Speicher, nicht Rechenleistung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Dokument spezifiziert typischerweise die Hardware-Systemvoraussetzungen?', 2, '[{"text": "Pflichtenheft", "correct": true, "because": "Enthält technische Details"}, {"text": "Lastenheft", "correct": false, "because": "Kundenwünsche, weniger technisch"}, {"text": "Rechnung", "correct": false, "because": "Kaufbezogen"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist der erste Schritt bei der Ermittlung der Hardware-Systemvoraussetzungen?', 3, '[{"text": "Analyse der Softwareanforderungen", "correct": true, "because": "Software definiert Bedarf"}, {"text": "Auswahl der Peripheriegeräte", "correct": false, "because": "Späterer Schritt"}, {"text": "Kostenkalkulation", "correct": false, "because": "Folgeprozess"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Einheit wird oft verwendet, um die Mindestanforderungen an den Arbeitsspeicher zu definieren?', 2, '[{"text": "Gigabyte (GB)", "correct": true, "because": "Standardmaß für RAM"}, {"text": "Megahertz (MHz)", "correct": false, "because": "Frequenz, nicht Kapazität"}, {"text": "Watt (W)", "correct": false, "because": "Leistungsaufnahme"}]'),
-- Multiple-Choice-Fragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Welche Komponenten werden bei der Festlegung der Hardware-Systemvoraussetzungen berücksichtigt?', 4, '[{"text": "Prozessor", "correct": true, "because": "Rechenleistung"}, {"text": "Arbeitsspeicher", "correct": true, "because": "Datenverarbeitung"}, {"text": "Festplatte", "correct": true, "because": "Speicherbedarf"}, {"text": "Tastatur", "correct": false, "because": "Peripherie, weniger relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Kriterien beeinflussen die Hardware-Systemvoraussetzungen?', 3, '[{"text": "Softwarekompatibilität", "correct": true, "because": "Technische Basis"}, {"text": "Leistungsanforderungen", "correct": true, "because": "Performancebedarf"}, {"text": "Skalierbarkeit", "correct": true, "because": "Zukunftsoption"}, {"text": "Farbe des Gehäuses", "correct": false, "because": "Ästhetisch, nicht technisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Risiken entstehen, wenn Hardware-Systemvoraussetzungen nicht korrekt definiert werden?', 3, '[{"text": "Systeminstabilität", "correct": true, "because": "Unzureichende Leistung"}, {"text": "Inkompatibilität", "correct": true, "because": "Software läuft nicht"}, {"text": "Kostenerhöhung", "correct": true, "because": "Nachtrag nötig"}, {"text": "Verzögerte Lieferung", "correct": false, "because": "Logistisch, nicht technisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte der Hardware-Systemvoraussetzungen müssen mit dem Kunden abgeklärt werden?', 4, '[{"text": "Minimale Leistungsanforderungen", "correct": true, "because": "Basis für Funktion"}, {"text": "Zukünftige Erweiterbarkeit", "correct": true, "because": "Langfristige Nutzung"}, {"text": "Betriebssystem-Kompatibilität", "correct": true, "because": "Softwareabhängigkeit"}, {"text": "Garantielaufzeit", "correct": false, "because": "Service, nicht technisch"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren können die Hardware-Systemvoraussetzungen während eines Projekts verändern?', 3, '[{"text": "Änderung der Software", "correct": true, "because": "Neuer Bedarf"}, {"text": "Kundenwunsch nach mehr Leistung", "correct": true, "because": "Anpassung nötig"}, {"text": "Technologische Entwicklungen", "correct": true, "because": "Bessere Optionen"}, {"text": "Änderung der Bürofläche", "correct": false, "because": "Nicht technisch relevant"}]'),
-- Richtig/Falsch-Kombinationsfragen (5 Stück)
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Hardware-Systemvoraussetzungen hängen von der Software ab. b) Peripheriegeräte bestimmen die CPU-Anforderungen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Software ja, Peripherie nicht direkt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Arbeitsspeicher wird in Gigabyte spezifiziert. b) Hardware-Systemvoraussetzungen ignorieren Betriebssysteme.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "GB ja, Betriebssystem relevant"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Hardware-Systemvoraussetzungen müssen skalierbar sein. b) Sie werden im Pflichtenheft dokumentiert.', 3, '[{"text": "Nur b) stimmt", "correct": true, "because": "Skalierbarkeit optional, Pflichtenheft ja"}, {"text": "Beides stimmt", "correct": false, "because": "a) ist nicht zwingend"}, {"text": "Nur a) stimmt", "correct": false, "because": "b) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "b) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen korrekt? a) Softwareanforderungen beeinflussen die Festplattengröße. b) Hardware-Systemvoraussetzungen sind unabhängig vom Kunden.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Festplatte ja, Kunde relevant"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Hardware-Systemvoraussetzungen berücksichtigen Prozessorleistung. b) Sie werden erst nach der Installation definiert.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Prozessor ja, Definition vorher"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist richtig"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]');

